package com.vandorlabs.neoforge.ramp;
import com.mojang.serialization.MapCodec;
import java.util.*;
import java.util.concurrent.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Private selective publication; actual disk boundaries and partial saves, not a public Ramp controller. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeRampPublicationChecks {
 private static final BlockPos ROOT=new BlockPos(23500,90,23500),CHEST=ROOT.east(11),STONE=ROOT.south(2),PART_A=ROOT.east(12),PART_B=ROOT.south(3),FUTURE=ROOT.east(13);
 private static final List<BlockPos> ALL=List.of(CHEST,STONE,PART_A,PART_B,FUTURE),SOURCES=List.of(CHEST,STONE),PARTS=List.of(PART_A,PART_B);
 private static NativeRampBlock rootBlock;private static Proxy proxy;private static BlockEntityType<NativeRampEntity> roots;private static BlockEntityType<NativeRampJournalPart> parts;private static ServerLevel level;private static ServerPlayer actor;private static NativeRampEntity owner;private static NativeRampJournal.Operation op;private static String mode;private static int phase,ticks,checks;private static boolean injected;private static CompletableFuture<Void> write,flush;
 private static boolean enabled(){return System.getProperty("vandorlabs.transmitterPhase","").startsWith("ramp-publication-");}
 private static final class Proxy extends BaseEntityBlock {Proxy(){super(BlockBehaviour.Properties.of().strength(2));}protected MapCodec<Proxy> codec(){return MapCodec.unit(this);}public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return System.getProperty("vandorlabs.transmitterPhase","").endsWith("factory-read")?null:new NativeRampJournalPart(parts,pos,state);}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {
  @SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{rootBlock=new NativeRampBlock(BlockBehaviour.Properties.of().strength(1),()->roots);proxy=new Proxy();h.register(ResourceLocation.parse("vandorlabs:ramp_publication_root"),rootBlock);h.register(ResourceLocation.parse("vandorlabs:ramp_publication_part"),proxy);});e.register(Registries.BLOCK_ENTITY_TYPE,h->{roots=BlockEntityType.Builder.<NativeRampEntity>of((p,s)->new NativeRampEntity(roots,p,s,false),rootBlock).build(null);parts=BlockEntityType.Builder.<NativeRampJournalPart>of((p,s)->new NativeRampJournalPart(parts,p,s),proxy).build(null);h.register(ResourceLocation.parse("vandorlabs:ramp_publication_root"),roots);h.register(ResourceLocation.parse("vandorlabs:ramp_publication_part"),parts);});}
 }
 @SubscribeEvent public static void start(ServerStartedEvent e){if(!enabled())return;level=e.getServer().overworld();mode=System.getProperty("vandorlabs.transmitterPhase").substring("ramp-publication-".length());System.out.println("[vandorlabs][ramp-publication] started mode="+mode);for(var pos:ALL){level.getChunkAt(pos);level.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);}level.getChunkAt(ROOT);actor=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(new UUID(0,5717),"RampPublication"));actor.setPos(ROOT.getX()+.5,ROOT.getY(),ROOT.getZ()+.5);actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);
  if(mode.endsWith("-write")){level.setBlock(ROOT,rootBlock.defaultBlockState(),18);for(var pos:ALL)level.setBlock(pos,Blocks.AIR.defaultBlockState(),18);level.setBlock(CHEST,Blocks.CHEST.defaultBlockState(),18);((ChestBlockEntity)level.getBlockEntity(CHEST)).setItem(0,new ItemStack(Items.DIAMOND,7));level.getBlockEntity(CHEST).getPersistentData().putString("RampPrivateBeforeImage","retained");level.setBlock(STONE,Blocks.STONE.defaultBlockState(),18);level.setBlock(STONE.below(),Blocks.STONE.defaultBlockState(),18);owner=(NativeRampEntity)level.getBlockEntity(ROOT);need(NativeRampAuthorization.authorize(owner,actor),"real installed location authority");level.getServer().saveEverything(true,true,true);NativeRampJournal.testFault=NativeRampPublicationChecks::fault;}
  else {owner=(NativeRampEntity)level.getBlockEntity(ROOT);need(NativeRampJournal.load(level)==NativeRampJournal.Status.READY,"startup journal admission completed");op=NativeRampJournal.atRoot(level,ROOT);if(mode.equals("normal-read")||mode.equals("arming-edit-read")||mode.equals("receipt-failure-read")){need(op==null,"retired selected operation");finished(false);return;}need(op!=null,"abrupt journal remains");if(mode.equals("vacated-read")){need(level.getBlockState(STONE).is(Blocks.STONE)&&!NativeRampHeldOwners.blocked(level,STONE),"new identical block remains a separate usable owner after restart state="+level.getBlockState(STONE)+" held="+NativeRampHeldOwners.blocked(level,STONE));need(NativeRampJournal.recover(level,op)==NativeRampJournal.Status.REFUSED,"identical occupied original refuses replay");need(level.getBlockState(STONE).is(Blocks.STONE)&&ownedParts()==2,"refusal leaves player block and journal proxies");level.setBlock(STONE,Blocks.AIR.defaultBlockState(),18);}else need(NativeRampHeldOwners.blocked(level,STONE)&&NativeRampHeldOwners.blocked(level,CHEST),"pre-vacated or restoring source holds exist before first gameplay");phase=4;}
 }
 private static void fault(String stage){if(injected)return;if(mode.equals("receipt-failure-write")&&stage.equals("after-publication")&&op!=null&&op.phase()==NativeRampJournal.Phase.COMMIT_PUBLICATION){injected=true;throw new IllegalStateException("fixture uncertain APPLIED receipt");}if(mode.equals("restoring-write")&&stage.equals("after-restoring-receipt")){injected=true;partialHalt("RESTORING durable before original publication");}if(mode.equals("armed-write")&&stage.equals("checkpoint-written")){injected=true;partialHalt("ARMED partial publication");}if(mode.equals("restored-write")&&stage.equals("after-restore")&&level.getBlockState(STONE).is(Blocks.STONE)&&level.getBlockEntity(CHEST) instanceof ChestBlockEntity){injected=true;partialHalt("RESTORING partial original save");}}
 private static void partialHalt(String label){try{var pos=new net.minecraft.world.level.ChunkPos(ROOT);var chunk=level.getChunkSource().getChunkNow(pos.x,pos.z);level.getChunkSource().chunkMap.write(pos,net.minecraft.world.level.chunk.storage.ChunkSerializer.write(level,chunk)).join();((com.vandorlabs.neoforge.mixin.NativeRampChunkStorageAccess)(Object)level.getChunkSource().chunkMap).vandorlabs$rampWorker().synchronize(true).join();level.noSave=true;System.out.println("[vandorlabs][ramp-publication] abrupt PASS "+label+" checks="+checks);System.out.flush();Runtime.getRuntime().halt(0);}catch(RuntimeException failure){throw failure;}}
 @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!enabled()||level==null)return;if(++ticks>1800)throw new AssertionError("Ramp publication timeout "+mode+" phase="+phase+" op="+(op==null?null:op.phase())+" error="+(op==null?null:op.error()));
  if(phase==0){var start=NativeRampJournal.preparePlatform(owner,actor,ALL,SOURCES,PARTS,proxy.defaultBlockState());need(start.status()!=NativeRampJournal.Status.REFUSED,"selected prepare admitted "+start.error());if(start.operation()==null)return;op=start.operation();phase=1;}
  if(phase==1){var status=NativeRampJournal.poll(level,op);if(status==NativeRampJournal.Status.PENDING)return;need(status==NativeRampJournal.Status.READY,"async preparation completed");need(!NativeRampHeldOwners.blocked(level,CHEST),"mere preparation remains usable");var chest=(ChestBlockEntity)level.getBlockEntity(CHEST);var wrapper=new net.neoforged.neoforge.items.wrapper.InvWrapper(chest);need(wrapper.extractItem(0,1,false).getCount()==1,"prepared inventory usable");chest.setItem(0,new ItemStack(Items.DIAMOND,7));need(level.setBlock(FUTURE,Blocks.GOLD_BLOCK.defaultBlockState(),18),"prepared future cell editable");level.setBlock(FUTURE,Blocks.AIR.defaultBlockState(),18);need(NativeRampJournal.arm(level,op,actor)==NativeRampJournal.Status.PENDING,"ARM write is pending, not rejection");need(NativeRampHeldOwners.blocked(level,CHEST)&&!NativeRampHeldOwners.blocked(level,FUTURE),"ARM holds only actual original sources");if(mode.equals("arming-edit-write"))need(level.setBlock(FUTURE,Blocks.GOLD_BLOCK.defaultBlockState(),18),"future remains editable during ARM fsync");phase=2;}
  if(phase==2){if(NativeRampJournal.poll(level,op)==NativeRampJournal.Status.PENDING)return;var status=NativeRampJournal.apply(level,op,actor);if(mode.equals("arming-edit-write")){need(status==NativeRampJournal.Status.REFUSED,"changed future clearance refuses before source removal");need(level.getBlockEntity(CHEST) instanceof ChestBlockEntity&&level.getBlockState(FUTURE).is(Blocks.GOLD_BLOCK),"ARM refusal retains both legitimate owners");phase=4;}else{need(status==NativeRampJournal.Status.PENDING,"publication awaits chunk+vacated receipt");need(NativeRampHeldOwners.blocked(level,CHEST)&&NativeRampHeldOwners.blocked(level,STONE),"vacated positions remain held until durable receipt");phase=3;}}
  if(phase==3){var status=NativeRampJournal.poll(level,op);if(status==NativeRampJournal.Status.REFUSED&&mode.equals("receipt-failure-write")){need(injected&&NativeRampHeldOwners.blocked(level,STONE),"caught post-publication receipt failure keeps original source holds");need(level.setBlock(FUTURE,Blocks.GOLD_BLOCK.defaultBlockState(),18),"future remains independent during failed receipt");checkpointFutureEdit();phase=4;return;}need(status!=NativeRampJournal.Status.REFUSED,"publication checkpoint "+op.error());if(status==NativeRampJournal.Status.PENDING)return;need(ownedParts()==2&&level.getBlockState(CHEST).isAir()&&level.getBlockState(STONE).isAir(),"one private journal owns original sources");need(!NativeRampHeldOwners.blocked(level,CHEST)&&!NativeRampHeldOwners.blocked(level,STONE)&&NativeRampHeldOwners.blocked(level,PART_A),"durable vacated receipt releases only source vacancies");need(level.setBlock(FUTURE,Blocks.GOLD_BLOCK.defaultBlockState(),18),"future path remains editable after publication");checkpointFutureEdit();
   if(mode.equals("factory-write"))partialHalt("APPLIED before missing-factory restart");if(mode.equals("normal-write")||mode.equals("vacated-write")){placeIdentical();need(NativeRampJournal.recover(level,op)==NativeRampJournal.Status.REFUSED,"new byte-identical player block is obstruction");need(ownedParts()==2&&level.getBlockState(STONE).is(Blocks.STONE),"refusal preserves both owners");if(mode.equals("vacated-write"))partialHalt("APPLIED plus legitimate identical player block");level.setBlock(STONE,Blocks.AIR.defaultBlockState(),18);}phase=4;}
  if(phase==4){var status=NativeRampJournal.recover(level,op);need(status!=NativeRampJournal.Status.REFUSED,"selected recovery "+op.error());if(status==NativeRampJournal.Status.DONE)finished(true);}
 }
 private static void checkpointFutureEdit(){var pos=new net.minecraft.world.level.ChunkPos(FUTURE);level.getChunkSource().chunkMap.write(pos,net.minecraft.world.level.chunk.storage.ChunkSerializer.write(level,level.getChunkSource().getChunkNow(pos.x,pos.z))).join();((com.vandorlabs.neoforge.mixin.NativeRampChunkStorageAccess)(Object)level.getChunkSource().chunkMap).vandorlabs$rampWorker().synchronize(true).join();}
 private static void placeIdentical(){actor.setPos(STONE.getX()+.5,STONE.getY(),STONE.getZ()-2);actor.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Blocks.STONE,1));var hit=new BlockHitResult(new Vec3(STONE.getX()+.5,STONE.getY(),STONE.getZ()+.5),Direction.UP,STONE.below(),false);var result=actor.gameMode.useItemOn(actor,level,actor.getMainHandItem(),net.minecraft.world.InteractionHand.MAIN_HAND,hit);need(result.consumesAction()&&actor.getMainHandItem().isEmpty()&&level.getBlockState(STONE).is(Blocks.STONE),"actual Survival BlockItem consumes one new identical block");}
 private static int ownedParts(){int count=0;for(var pos:PARTS)if(level.getBlockEntity(pos) instanceof NativeRampJournalPart part&&part.belongs(op.id(),ROOT))count++;return count;}
 private static void finished(boolean writePhase){need(level.getBlockState(STONE).is(Blocks.STONE)&&level.getBlockEntity(CHEST) instanceof ChestBlockEntity,"original blocks restored");var chest=(ChestBlockEntity)level.getBlockEntity(CHEST);need(chest.getItem(0).is(Items.DIAMOND)&&chest.getItem(0).getCount()==7&&chest.getPersistentData().getString("RampPrivateBeforeImage").equals("retained"),"exact original inventory and private payload");need(level.getBlockState(PART_A).isAir()&&level.getBlockState(PART_B).isAir(),"proxies retired");if(!mode.startsWith("armed-"))need(level.getBlockState(FUTURE).is(Blocks.GOLD_BLOCK),"legitimate future-cell edit preserved");need(!NativeRampHeldOwners.active(level),"all holds retired");level.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][ramp-publication] "+(mode.endsWith("-write")?"write":"read")+" PASS checks="+checks+" private protocol only");level.getServer().halt(false);level=null;}
 private static void need(boolean ok,String text){checks++;if(!ok)throw new AssertionError("Ramp publication "+mode+": "+text);}
}
